export const AsyncSearch: Story = {
  parameters: {
    docs: {
      description: { story: "Open the project picker and type a query. This story simulates a delayed request locally, cancels obsolete requests, and hides stale results while searching. The first arriving match is highlighted; use arrow keys and Enter to choose it. Search for a missing project to see the empty state, then clear the query to restore the longer list and its thin scrollbar.

The flush search header stays outside the scrolling list and retains its separator. Header height follows our search sizing on desktop and mobile; the list uses the space left by the actual header rather than subtracting a fixed height. For a real service, cancel the request and use `filter={null}` when the service already filters results.

Show a centered spinner while results are pending, with an accessible search status. Use `ComboboxStatus` for loading or error announcements and `ComboboxEmpty` for a completed search with no matches. Keep Status mounted while the popup is open and update its children; hiding or conditionally mounting the live region can prevent announcements. The list's `aria-busy` communicates that results are still arriving." },
      source: { code: "import { useEffect, useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import { Spinner } from "@/registry/erbium/ui/spinner";
import {
  Combobox,
  ComboboxTrigger,
  ComboboxValue,
  ComboboxSearchInput,
  ComboboxContent,
  ComboboxList,
  ComboboxItem,
  ComboboxEmpty,
  ComboboxStatus,
} from "@/registry/erbium/ui/combobox";

const projects = [
  "Design system",
  "Documentation",
  "Website",
  "Mobile app",
  "Research",
  "Product analytics",
  "Release planning",
  "Customer feedback",
  "Engineering tools",
  "Team workspace",
  "Design review",
  "Design resources",
  "Design experiments",
  "Design handoff",
  "Design templates",
  "Design archive",
].map((name, id) => ({ id, name }));

type Project = (typeof projects)[number];

export default function AsyncSearchExample() {
  const [query, setQuery] = useState("");
  const [response, setResponse] = useState({ items: projects, query: "" });
  const [selected, setSelected] = useState<Project | null>(null);
  const [preview, setPreview] = useState("");
  const loading = response.query !== query;
  useEffect(() => {
    const timer = setTimeout(() => {
      setResponse({
        items: projects.filter((project) =>
          project.name.toLowerCase().includes(query.toLowerCase()),
        ),
        query,
      });
    }, 350);

    return () => {
      clearTimeout(timer);
    };
  }, [query]);

  return (
    <div className="grid gap-related">
      <Combobox
        items={loading ? [] : response.items}
        filter={null}
        autoHighlight
        value={selected}
        onValueChange={setSelected}
        onInputValueChange={setQuery}
        itemToStringLabel={(project) => project.name}
        onItemHighlighted={(project) => {
          setPreview(project?.name ?? "");
        }}
      >
        <ComboboxTrigger render={<Button variant="outline" className="w-72 justify-between" />}>
          <ComboboxValue placeholder="Find a project" />
        </ComboboxTrigger>
        <ComboboxContent className="w-72">
          <ComboboxSearchInput aria-label="Search projects" placeholder="Search projects…" />
          <ComboboxStatus className="p-0">
            {loading && (
              <span className="flex h-10 items-center justify-center">
                <Spinner aria-hidden />
                <span className="sr-only">Searching projects</span>
              </span>
            )}
          </ComboboxStatus>
          <ComboboxEmpty className="not-empty:flex not-empty:h-10 not-empty:items-center not-empty:justify-center not-empty:py-0">
            {loading ? null : "No projects found."}
          </ComboboxEmpty>
          <ComboboxList aria-busy={loading || undefined}>
            {(project: Project) => (
              <ComboboxItem key={project.id} value={project}>
                {project.name}
              </ComboboxItem>
            )}
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
      <p className="text-caption text-muted-foreground">Highlighted: {preview || "none"}</p>
      <output className="text-control">Selected: {selected?.name ?? "none"}</output>
    </div>
  );
}
" },
    },
  },
  render: AsyncSearchExample,
};

