import { useEffect, useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import { Spinner } from "@/registry/erbium/ui/spinner";
import {
  Combobox,
  ComboboxTrigger,
  ComboboxValue,
  ComboboxSearchInput,
  ComboboxContent,
  ComboboxList,
  ComboboxItem,
  ComboboxEmpty,
  ComboboxStatus,
} from "@/registry/erbium/ui/combobox";

const projects = [
  "Design system",
  "Documentation",
  "Website",
  "Mobile app",
  "Research",
  "Product analytics",
  "Release planning",
  "Customer feedback",
  "Engineering tools",
  "Team workspace",
  "Design review",
  "Design resources",
  "Design experiments",
  "Design handoff",
  "Design templates",
  "Design archive",
].map((name, id) => ({ id, name }));

type Project = (typeof projects)[number];

export default function AsyncSearchExample() {
  const [query, setQuery] = useState("");
  const [response, setResponse] = useState({ items: projects, query: "" });
  const [selected, setSelected] = useState<Project | null>(null);
  const [preview, setPreview] = useState("");
  const loading = response.query !== query;
  useEffect(() => {
    const timer = setTimeout(() => {
      setResponse({
        items: projects.filter((project) =>
          project.name.toLowerCase().includes(query.toLowerCase()),
        ),
        query,
      });
    }, 350);

    return () => {
      clearTimeout(timer);
    };
  }, [query]);

  return (
    <div className="grid gap-related">
      <Combobox
        items={loading ? [] : response.items}
        filter={null}
        autoHighlight
        value={selected}
        onValueChange={setSelected}
        onInputValueChange={setQuery}
        itemToStringLabel={(project) => project.name}
        onItemHighlighted={(project) => {
          setPreview(project?.name ?? "");
        }}
      >
        <ComboboxTrigger render={<Button variant="outline" className="w-72 justify-between" />}>
          <ComboboxValue placeholder="Find a project" />
        </ComboboxTrigger>
        <ComboboxContent className="w-72">
          <ComboboxSearchInput aria-label="Search projects" placeholder="Search projects…" />
          <ComboboxStatus className="p-0">
            {loading && (
              <span className="flex h-10 items-center justify-center">
                <Spinner aria-hidden />
                <span className="sr-only">Searching projects</span>
              </span>
            )}
          </ComboboxStatus>
          <ComboboxEmpty className="not-empty:flex not-empty:h-10 not-empty:items-center not-empty:justify-center not-empty:py-0">
            {loading ? null : "No projects found."}
          </ComboboxEmpty>
          <ComboboxList aria-busy={loading || undefined}>
            {(project: Project) => (
              <ComboboxItem key={project.id} value={project}>
                {project.name}
              </ComboboxItem>
            )}
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
      <p className="text-caption text-muted-foreground">Highlighted: {preview || "none"}</p>
      <output className="text-control">Selected: {selected?.name ?? "none"}</output>
    </div>
  );
}

